package chat.oldy;
import android.text.*;import android.widget.*;import org.json.*;import java.util.Locale;
final class SignupHandle {
 static void bind(MainActivity a,EditText input,TextView status,TextView submit){final int[] generation={0};final Runnable[] pending={null};final android.view.View page=a.root;Runnable check=()->{int sequence=++generation[0];if(pending[0]!=null)a.ui.removeCallbacks(pending[0]);String h=input.getText().toString().trim().replaceFirst("^@","").toLowerCase(Locale.ROOT);submit.setEnabled(false);submit.setAlpha(.5f);status.setTextColor(a.MUTED);if(!h.matches("[a-z0-9_]{3,24}")){status.setText("От 3 до 24 символов: латиница, цифры или _");return;}status.setText("Проверяем @"+h+"…");pending[0]=()->a.work.execute(()->{try{JSONObject result=a.api.call("/handles?handle="+h,null,"");a.runOnUiThread(()->{if(sequence!=generation[0]||page!=a.root)return;boolean free=result.optBoolean("available");status.setText(free?"✓ @"+h+" свободен":"@"+h+" уже занят");status.setTextColor(free?(a.light?0xff177560:0xff86dfc6):(a.light?0xffac3457:0xfffba5b5));submit.setEnabled(free);submit.setAlpha(free?1:.5f);});}catch(Exception e){a.runOnUiThread(()->{if(sequence==generation[0]&&page==a.root)status.setText("Не удалось проверить. Нажми здесь, чтобы повторить.");});}});a.ui.postDelayed(pending[0],400);};input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){check.run();}public void afterTextChanged(Editable e){}});status.setOnClickListener(v->check.run());check.run();}
}
